const header=document.querySelector('header');
const menu=document.querySelector('.menu');
const nav=document.querySelector('nav');
function syncHeader(){header.classList.toggle('scrolled',scrollY>60)}
addEventListener('scroll',syncHeader,{passive:true});syncHeader();
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');nav.classList.toggle('open',open)});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menu')}));
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));document.body.classList.add('animate-ready')}
const form=document.querySelector('#quote-form'),dialog=document.querySelector('#quote-dialog'),summary=document.querySelector('#summary'),status=document.querySelector('#copy-status');
const dateInput=form.elements.data;const today=new Date();dateInput.min=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');
form.addEventListener('submit',event=>{event.preventDefault();const d=new FormData(form);const val=k=>String(d.get(k)||'').trim();if(!val('nome')||!val('origem')||!val('destino')||!val('carga')){form.reportValidity();return}const date=val('data')?val('data').split('-').reverse().join('/'):'A combinar';summary.value=`Olá, equipe PURM! Gostaria de conversar sobre uma cotação de transporte.\n\nContato desejado: ${val('contato_data').split('-').reverse().join('/')} às ${val('contato_hora')} (Brasília)\n\nNome: ${val('nome')}\nWhatsApp: ${val('telefone')}\nE-mail: ${val('email')}\nEmpresa: ${val('empresa')||'Não informada'}\nOrigem: ${val('origem')}\nDestino: ${val('destino')}\nData desejada: ${date}\nPeso aproximado: ${val('peso')||'A informar'}\n\nDescrição da carga:\n${val('carga')}\n\nPodem confirmar a disponibilidade e as condições de atendimento?`;status.textContent='';dialog.showModal()});
document.querySelectorAll('dialog .close').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}));
document.querySelector('#copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(summary.value);status.textContent='Pedido copiado. Agora é só encaminhar à equipe PURM.'}catch{summary.focus();summary.select();status.textContent='Selecione o texto acima e use a opção Copiar do seu dispositivo.'}});
document.querySelector('#download').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([summary.value],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='pedido-de-cotacao-purm.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Pedido preparado para download.'});


const dateOptions=document.querySelector('#date-options'),timeOptions=document.querySelector('#time-options');
const businessNow=()=>new Date(new Date().toLocaleString('en-US',{timeZone:'America/Recife'}));
const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const times=['09:00','10:30','14:00','15:30','17:00'];
const now=businessNow(),cursor=new Date(now);cursor.setHours(12,0,0,0);cursor.setDate(cursor.getDate()+1);
for(let count=0;count<10;cursor.setDate(cursor.getDate()+1)){if([0,6].includes(cursor.getDay()))continue;const d=new Date(cursor),key=dateKey(d),button=document.createElement('button');button.type='button';button.className='schedule-option';button.setAttribute('aria-pressed','false');button.setAttribute('aria-label',d.toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'}));button.innerHTML=`<span>${d.toLocaleDateString('pt-BR',{weekday:'short'}).replace('.','')}</span><b>${d.getDate()}</b><span>${d.toLocaleDateString('pt-BR',{month:'short'}).replace('.','')}</span>`;button.addEventListener('click',()=>{dateOptions.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed','false'));button.setAttribute('aria-pressed','true');form.elements.contato_data.value=key;document.querySelector('#schedule-error').textContent=''});dateOptions.append(button);count++}
times.forEach(time=>{const button=document.createElement('button');button.type='button';button.className='schedule-option';button.textContent=time;button.setAttribute('aria-pressed','false');button.addEventListener('click',()=>{timeOptions.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed','false'));button.setAttribute('aria-pressed','true');form.elements.contato_hora.value=time;document.querySelector('#schedule-error').textContent=''});timeOptions.append(button)});
function setStep(details){document.querySelector('#schedule-step').hidden=details;document.querySelector('#details-step').hidden=!details;document.querySelector('#progress-one').classList.toggle('active',!details);document.querySelector('#progress-two').classList.toggle('active',details)}
document.querySelector('#schedule-next').addEventListener('click',()=>{if(!form.elements.contato_data.value||!form.elements.contato_hora.value){document.querySelector('#schedule-error').textContent='Selecione uma data e um horário para continuar.';return}document.querySelector('#chosen-schedule').textContent=`Conversa solicitada para ${form.elements.contato_data.value.split('-').reverse().join('/')} às ${form.elements.contato_hora.value} · Brasília`;setStep(true);form.elements.nome.focus()});
document.querySelector('.back-step').addEventListener('click',()=>{setStep(false);document.querySelector('#schedule-next').focus()});
if(matchMedia('(prefers-reduced-motion: reduce)').matches){document.querySelectorAll('.brazil-map animateMotion,.brazil-map animate').forEach(el=>el.remove())}

const runningTruck=document.querySelector('.circle-link');
runningTruck.addEventListener('pointerenter',event=>{if(event.pointerType!=='mouse'||matchMedia('(prefers-reduced-motion: reduce)').matches)return;runningTruck.classList.add('is-driving')});
runningTruck.querySelector('.transport-icon').addEventListener('animationend',event=>{if(event.animationName==='truck-drive-away')runningTruck.classList.remove('is-driving')});
